package net.officefloor.hq.app.rate;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import net.officefloor.hq.app.sheet.AsOf;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/** The sheet's rate for each grade that has one (as they stood at the end of the as-of date, when one is given),
 *  then its parents' rates, nearest first, each marked with its level. */
public class RespondWithRates {
    public void respond(@PathVariable("sheetId") String sheetId,
            @RequestParam(name = "asOf", required = false) String asOf, RateRepository repository,
            ObjectResponse<List<RateResponse>> response) {
        String id = sheetId.trim();
        LocalDate end = AsOf.parse(asOf);
        List<String> sheets = new ArrayList<>();
        sheets.add(id);
        sheets.addAll(repository.parents(id));
        List<RateResponse> shown = new ArrayList<>();
        for (int level = 0; level < sheets.size(); level++) {
            List<Rate> rates = end != null ? repository.listAsOf(sheets.get(level), end) : repository.list(sheets.get(level));
            for (Rate r : rates) {
                shown.add(RateResponse.from(r, level));
            }
        }
        response.send(shown);
    }
}
package net.officefloor.hq.app.rate;

/** A rate as the screen shows it: the grade, the percent with two decimals, and the from-date
 *  (yyyy-mm-dd, or null when it applies from the beginning of time) and the to-date (yyyy-mm-dd, or null when it has no end), and the level it comes from (0: the sheet's own; 1: its parent's,
 *  2: the parent's parent's, and so on), and its version count (how many have been set for the grade from that from-date). */
public record RateResponse(String grade, String rate, String from, String to, int level, int version) {
    public static RateResponse from(Rate r) {
        return from(r, 0);
    }

    public static RateResponse from(Rate r, int level) {
        return new RateResponse(r.grade(), r.pct().toPlainString(), r.from() != null ? r.from().toString() : null,
                r.to() != null ? r.to().toString() : null, level, r.version());
    }
}
