        return new RateResponse(r.grade(), r.pct().toPlainString(), r.from() != null ? r.from().toString() : null,
                r.to() != null ? r.to().toString() : null, level, r.version(), r.after(),
                older.stream().map(Older::from).toList());
    }
}
